INSERT INTO "PipelineRun" (id,"organizationId","pipelineId",status,"triggeredBy","correlationId","updatedAt") VALUES ('draft_run','draft_org','ai_coding','running','draft_actor','draft_corr',now());
INSERT INTO "PipelineStageRun" (id,"runId","stageId","stageKind",ordering,status,"aiClaimGeneration","updatedAt") SELECT 'draft_stage_'||n,'draft_run','propose_'||n,'code_propose',n,'running','draft_generation_'||n,now() FROM generate_series(1,5) n;
INSERT INTO "UsageEvent" (id,"organizationId","externalUsageId","eventKind",provider,model,"inputTokens","outputTokens","costCents","billedCents","billingStatus","triggeredBy","correlationId") SELECT 'draft_usage_'||n,'draft_org','draft_external_'||n,'ai_invocation','vercel_gateway','synthetic/model',5,2,CASE WHEN n=4 THEN 7 ELSE 0 END,CASE WHEN n=4 THEN 11 ELSE 0 END,CASE WHEN n=4 THEN 'settled' ELSE 'pending' END,'draft_actor','draft_corr' FROM generate_series(3,4) n;
INSERT INTO "AIUsageReservation" (id,"organizationId","idempotencyKey","reservedCents",status,"correlationId","usageEventId","expiresAt","settledCents","settledAt","releasedAt","updatedAt") SELECT 'draft_hold_'||n,'draft_org','draft_key_'||n,17*n,(ARRAY['reserved','dispatch_unknown','pending_settlement','settled','released'])[n],'draft_corr',CASE WHEN n IN (3,4) THEN 'draft_usage_'||n END,now()+interval '5 minutes',CASE WHEN n=4 THEN 11 END,CASE WHEN n=4 THEN now() END,CASE WHEN n=5 THEN now() END,now() FROM generate_series(1,5) n;
INSERT INTO "PipelineAICallReservation" (id,"organizationId","runId","stageRunId",phase,"claimGeneration","idempotencyKey","workspaceReservationId","actorId","correlationId","estimatedCents","capCents","capSource",status,"usageEventId","externalUsageId","providerCents","dispatchedAt","settledAt","releasedAt","updatedAt") SELECT 'draft_call_'||n,'draft_org','draft_run','draft_stage_'||n,'initial','draft_generation_'||n,'draft_key_'||n,'draft_hold_'||n,'draft_actor','draft_corr',17*n,500,'platform_default',(ARRAY['reserved','dispatch_unknown','pending_settlement','settled','released'])[n],CASE WHEN n IN (3,4) THEN 'draft_usage_'||n END,CASE WHEN n IN (3,4) THEN 'draft_external_'||n END,CASE WHEN n=4 THEN 7 END,CASE WHEN n IN (2,3,4) THEN now() END,CASE WHEN n=4 THEN now() END,CASE WHEN n=5 THEN now() END,now() FROM generate_series(1,5) n;
